import { getEnv } from "../../../src/platform/index.js";
import { ENVIRONMENT_PROJECT_REFERENCE_NAMES, resolveEnvironmentProjectReference, } from "../../shared/config.js";
import { createSuccessEnvelope, isJsonMode, outputJson } from "../../shared/json-output.js";
import { bold, dim } from "../../ui/colors.js";
const ENV_OVERRIDES = {
    apiBaseUrl: "VERYFRONT_API_BASE_URL",
    apiToken: "VERYFRONT_API_TOKEN",
    nodeEnv: "NODE_ENV",
    veryfrontEnv: "VERYFRONT_ENV",
    debug: "VERYFRONT_DEBUG",
};
export async function detectConfigSource(projectDir) {
    const { createFileSystem } = await import("../../../src/platform/index.js");
    const { join } = await import("../../../src/platform/compat/path/index.js");
    const fs = createFileSystem();
    for (const name of [
        "veryfront.config.ts",
        "veryfront.config.js",
        "veryfront.json",
    ]) {
        if (await fs.exists(join(projectDir, name)))
            return name;
    }
    if (await fs.exists(join(projectDir, ".veryfront", "project.json"))) {
        return ".veryfront/project.json";
    }
    return null;
}
export function getEnvOverrides() {
    const overrides = [];
    for (const envVar of ENVIRONMENT_PROJECT_REFERENCE_NAMES) {
        if (getEnv(envVar))
            overrides.push(`projectSlug (${envVar})`);
    }
    for (const [field, envVar] of Object.entries(ENV_OVERRIDES)) {
        if (getEnv(envVar))
            overrides.push(`${field} (${envVar})`);
    }
    return overrides;
}
export async function getConfigCommandData(projectDir) {
    const { getEnvironmentConfig } = await import("../../../src/config/index.js");
    const config = getEnvironmentConfig();
    const { readConfigFile } = await import("../../shared/config.js");
    const { resolveCliApiUrl } = await import("../../shared/constants.js");
    const { PROJECT_LINK_RELATIVE_PATH, readProjectLinkForControlPlane, } = await import("../../shared/project-link.js");
    const { hasToken } = await import("../../auth/token-store.js");
    const detectedConfigSource = await detectConfigSource(projectDir);
    const envOverrides = getEnvOverrides();
    const fileConfig = await readConfigFile(projectDir);
    const environmentProjectReference = resolveEnvironmentProjectReference()?.reference;
    const linkedProjectSlug = !config.projectSlug && !fileConfig?.projectSlug &&
        !environmentProjectReference
        ? (await readProjectLinkForControlPlane(projectDir, resolveCliApiUrl(config, fileConfig?.apiUrl)))?.projectSlug
        : undefined;
    // `whoami` authenticates from the CLI token store as well as the environment
    // token, so `config` has to consult both or it reports "Authenticated: no"
    // for a developer who is logged in.
    const hasApiToken = !!(config.apiToken ?? fileConfig?.apiToken);
    const hasStoredToken = await hasToken(config);
    return {
        projectSlug: config.projectSlug ?? fileConfig?.projectSlug ?? environmentProjectReference ??
            linkedProjectSlug ?? null,
        nodeEnv: config.nodeEnv,
        veryfrontEnv: config.veryfrontEnv || null,
        apiBaseUrl: config.apiBaseUrl,
        debug: config.debug,
        ci: config.ci,
        hasApiToken,
        hasStoredToken,
        authenticated: hasApiToken || hasStoredToken,
        configSource: linkedProjectSlug
            ? PROJECT_LINK_RELATIVE_PATH
            : detectedConfigSource === ".veryfront/project.json"
                ? null
                : detectedConfigSource,
        envOverrides,
    };
}
export async function handleConfigCommand(_args) {
    const { cwd } = await import("../../../src/platform/index.js");
    const configData = await getConfigCommandData(cwd());
    if (isJsonMode()) {
        await outputJson(createSuccessEnvelope("config", configData));
        return;
    }
    console.log();
    console.log(`  ${bold("Project Configuration")}`);
    console.log();
    console.log(`  ${dim("Project slug:")}  ${configData.projectSlug ?? "(not set)"}`);
    console.log(`  ${dim("Environment:")}   ${configData.nodeEnv}`);
    console.log(`  ${dim("VF Environment:")} ${configData.veryfrontEnv ?? "(not set)"}`);
    console.log(`  ${dim("API endpoint:")}  ${configData.apiBaseUrl}`);
    console.log(`  ${dim("Debug:")}         ${configData.debug}`);
    console.log(`  ${dim("CI:")}            ${configData.ci}`);
    console.log(`  ${dim("Authenticated:")} ${configData.authenticated ? "yes" : "no"}`);
    console.log(`  ${dim("Config file:")}   ${configData.configSource ?? "(none)"}`);
    if (configData.envOverrides.length > 0) {
        console.log(`  ${dim("Env overrides:")}  ${configData.envOverrides.join(", ")}`);
    }
    console.log();
}
